-- Published Rider–Waite–Smith 1909 cards. Source: Wikimedia Commons original-deck scans; all 78 file pages show Public Domain Mark.
select public.import_whimsy_content('[{"id":"tarot-major-00","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Fool","body":"The traveler steps toward an unknown path with curiosity; a fresh start asks for openness and a little faith.","metadata":{"number":0,"reversed":"Pause before leaping, or notice where fear of looking foolish has closed a useful door.","symbolism":"A figure approaches a cliff with a white rose and small dog; innocence meets the edge of experience.","question":"What new beginning feels worth a thoughtful risk?","element":"varies","artPath":"/tarot/rws1909/00-fool.jpg"},"tags":["beginning","trust","possibility"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_00_Fool.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-01","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Magician","body":"Tools are already on the table; focused intention turns an idea into something tangible.","metadata":{"number":1,"reversed":"Scattered energy or a polished performance may be hiding the work that actually matters.","symbolism":"One hand points upward while the other reaches earth, linking inspiration to action through the four suit tools.","question":"Which skill could you put to work today?","element":"varies","artPath":"/tarot/rws1909/01-magician.jpg"},"tags":["agency","focus","skill"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_01_Magician.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-02","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The High Priestess","body":"Quiet observation may reveal more than another immediate answer; trust what you know beneath the noise.","metadata":{"number":2,"reversed":"A secret may need gentle examination, or intuition may be confused with avoidance.","symbolism":"She sits between dark and light pillars with a scroll and veil, guarding knowledge that unfolds slowly.","question":"What have you sensed but not yet named?","element":"varies","artPath":"/tarot/rws1909/02-high-priestess.jpg"},"tags":["intuition","mystery","inner knowledge"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_02_High_Priestess.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-03","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Empress","body":"Care and patience help an idea, relationship, or body grow into its own season.","metadata":{"number":3,"reversed":"Overgiving or neglecting your own needs can make abundance feel strangely thin.","symbolism":"Wheat, flowing water, and a starry crown place creativity within a generous living landscape.","question":"What needs tending rather than forcing?","element":"varies","artPath":"/tarot/rws1909/03-empress.jpg"},"tags":["nurture","abundance","creation"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_03_Empress.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-04","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Emperor","body":"Clear boundaries and steady responsibility can give an ambitious plan a reliable shape.","metadata":{"number":4,"reversed":"Rigid control may be protecting you from uncertainty while limiting everyone else''s room.","symbolism":"A ruler sits on a stone throne marked by rams, holding symbols of authority in a stark landscape.","question":"Where would a clear boundary make life easier?","element":"varies","artPath":"/tarot/rws1909/04-emperor.jpg"},"tags":["structure","boundaries","stewardship"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_04_Emperor.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-05","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Hierophant","body":"A trusted practice, teacher, or community can offer useful wisdom before you improvise your own way.","metadata":{"number":5,"reversed":"A rule may be outliving its purpose; ask whether you are following it by choice.","symbolism":"A ceremonial teacher sits between pillars as two students receive instruction below.","question":"Which tradition supports you, and which one needs revision?","element":"varies","artPath":"/tarot/rws1909/05-hierophant.jpg"},"tags":["tradition","teaching","belonging"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_05_Hierophant.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-06","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Lovers","body":"A meaningful choice becomes clearer when your values and commitments are allowed into the conversation.","metadata":{"number":6,"reversed":"Attraction or approval may be replacing honest alignment with what you truly want.","symbolism":"Two figures stand beneath an angel, with contrasting trees behind them.","question":"What choice feels most aligned with your values?","element":"varies","artPath":"/tarot/rws1909/06-lovers.jpg"},"tags":["choice","alignment","connection"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_06_Lovers.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-07","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Chariot","body":"Choose a direction and coordinate competing impulses rather than waiting for a perfectly smooth road.","metadata":{"number":7,"reversed":"Pushing harder without checking the route can become motion without progress.","symbolism":"A charioteer faces two differently colored sphinxes beneath a starry canopy.","question":"What would deliberate forward motion look like here?","element":"varies","artPath":"/tarot/rws1909/07-chariot.jpg"},"tags":["direction","will","momentum"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_07_Chariot.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-08","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"Strength","body":"Gentle courage can work where force fails; steady care is its own form of strength.","metadata":{"number":8,"reversed":"Suppressed frustration or self-doubt may need compassion before it can change.","symbolism":"A calm figure closes a lion''s mouth beneath the infinity symbol.","question":"Where could you try patience instead of pressure?","element":"varies","artPath":"/tarot/rws1909/08-strength.jpg"},"tags":["courage","gentleness","patience"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_08_Strength.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-09","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Hermit","body":"Step back long enough to hear your own thinking; solitude can clarify the next small step.","metadata":{"number":9,"reversed":"Isolation may have become a hiding place, or noise may be keeping you from reflection.","symbolism":"A cloaked traveler holds a lantern high on a mountain path.","question":"What becomes clearer when you have quiet?","element":"varies","artPath":"/tarot/rws1909/09-hermit.jpg"},"tags":["solitude","inquiry","guidance"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_09_Hermit.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-10","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"Wheel of Fortune","body":"Conditions are shifting; meet the turn with adaptability rather than pretending everything is fixed.","metadata":{"number":10,"reversed":"Trying to control every outcome may make change feel more frightening than it is.","symbolism":"A turning wheel is surrounded by symbolic creatures studying open books.","question":"What is changing, and what remains yours to choose?","element":"varies","artPath":"/tarot/rws1909/10-wheel-of-fortune.jpg"},"tags":["cycles","change","timing"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_10_Wheel_of_Fortune.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-11","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"Justice","body":"Look at the evidence, own your part, and seek a fair outcome with clear eyes.","metadata":{"number":11,"reversed":"A rushed verdict or convenient story may be obscuring the full picture.","symbolism":"A seated figure holds balanced scales and an upright sword.","question":"What facts deserve a more honest hearing?","element":"varies","artPath":"/tarot/rws1909/11-justice.jpg"},"tags":["fairness","accountability","clarity"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_11_Justice.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-12","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Hanged Man","body":"A voluntary pause can reveal an angle that pushing forward would miss.","metadata":{"number":12,"reversed":"Waiting without reflection may be stagnation disguised as patience.","symbolism":"A calm figure hangs by one foot with a halo, seeing the world upside down.","question":"What might change if you viewed this differently?","element":"varies","artPath":"/tarot/rws1909/12-hanged-man.jpg"},"tags":["pause","perspective","surrender"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_12_Hanged_Man.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-13","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"Death","body":"An ending can make room for a different life chapter; let the old form complete itself.","metadata":{"number":13,"reversed":"Clinging to a finished chapter can delay a kinder transition.","symbolism":"A skeletal rider moves past fallen figures toward a sunrise between towers.","question":"What are you ready to let end gently?","element":"varies","artPath":"/tarot/rws1909/13-death.jpg"},"tags":["ending","transition","renewal"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_13_Death.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-14","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"Temperance","body":"Combine different needs with care; a sustainable rhythm may be more powerful than extremes.","metadata":{"number":14,"reversed":"The mixture may be out of balance, or moderation may have become an excuse to avoid a decision.","symbolism":"An angel pours water between two cups with one foot on land and one in water.","question":"What needs a more workable balance?","element":"varies","artPath":"/tarot/rws1909/14-temperance.jpg"},"tags":["balance","integration","pacing"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_14_Temperance.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-15","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Devil","body":"Notice the bargain that keeps you stuck; naming it is a first step toward choice.","metadata":{"number":15,"reversed":"Shame may be deepening a pattern that needs understanding and support.","symbolism":"Two figures stand loosely chained beneath a horned figure, suggesting bonds that can be examined.","question":"What hold on you might be looser than it feels?","element":"varies","artPath":"/tarot/rws1909/15-devil.jpg"},"tags":["attachment","habit","choice"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_15_Devil.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-16","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Tower","body":"A sudden change may expose what was unstable; respond to what is real before rebuilding.","metadata":{"number":16,"reversed":"Fear of disruption may be keeping a fragile structure standing too long.","symbolism":"Lightning strikes a tower and its crown falls as figures descend.","question":"What truth has become too clear to ignore?","element":"varies","artPath":"/tarot/rws1909/16-tower.jpg"},"tags":["disruption","revelation","rebuilding"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_16_Tower.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-17","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Star","body":"After difficulty, small acts of trust and restoration can make the future feel possible again.","metadata":{"number":17,"reversed":"Hope may need nourishment, or comparison may be dimming your own light.","symbolism":"A figure pours water onto earth and pool beneath a large star and seven smaller ones.","question":"What would help hope feel practical today?","element":"varies","artPath":"/tarot/rws1909/17-star.jpg"},"tags":["hope","restoration","openness"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_17_Star.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-18","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Moon","body":"Not every shadow is a warning; move carefully while feelings and facts become clearer.","metadata":{"number":18,"reversed":"Confusion may be growing because imagination is filling gaps that evidence could answer.","symbolism":"A moon hangs over a winding path between towers, with dog, wolf, and crayfish below.","question":"Which part is known, and which part is imagined?","element":"varies","artPath":"/tarot/rws1909/18-moon.jpg"},"tags":["uncertainty","dreams","intuition"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_18_Moon.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-19","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The Sun","body":"Let a clear success be visible; warmth and simple pleasure deserve space too.","metadata":{"number":19,"reversed":"A bright moment need not erase harder feelings, and forced cheer can flatten the truth.","symbolism":"A child rides beneath a radiant sun and sunflowers, carrying a red banner.","question":"What good thing can you allow yourself to enjoy?","element":"varies","artPath":"/tarot/rws1909/19-sun.jpg"},"tags":["joy","visibility","vitality"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_19_Sun.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-20","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"Judgement","body":"A past chapter can be understood without being relived; answer the call to begin differently.","metadata":{"number":20,"reversed":"Harsh self-judgment may be preventing the honest repair that would set you free.","symbolism":"An angel''s trumpet calls figures from open graves toward a distant horizon.","question":"What are you ready to answer for and move beyond?","element":"varies","artPath":"/tarot/rws1909/20-judgement.jpg"},"tags":["reckoning","renewal","calling"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_20_Judgement.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-major-21","version":1,"experience":"tarot","category":"Major Arcana","state":"published","title":"The World","body":"A cycle has reached its own shape; recognize what you learned before stepping onward.","metadata":{"number":21,"reversed":"A final detail or unmet expectation may be keeping you from acknowledging real completion.","symbolism":"A dancing figure within a wreath is framed by four symbolic creatures.","question":"What have you completed that deserves recognition?","element":"varies","artPath":"/tarot/rws1909/21-world.jpg"},"tags":["completion","integration","wholeness"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_21_World.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-01","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Ace of Wands","body":"A lively idea wants a first experiment, even if the full plan is not ready.","metadata":{"number":1,"reversed":"The spark may be buried under delay, or excitement may need a clearer direction.","symbolism":"A hand offers a budding wand above a fertile landscape.","question":"What small action would give this idea air?","element":"Fire","artPath":"/tarot/rws1909/wands-01.jpg"},"tags":["spark","initiative","creative energy"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_01.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-02","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Two of Wands","body":"You can see farther from this vantage; compare possible routes before committing.","metadata":{"number":2,"reversed":"Staying at the planning stage may feel safe while the world waits outside.","symbolism":"A figure holds a globe by a parapet, looking beyond familiar walls.","question":"Which horizon is worth preparing for?","element":"Fire","artPath":"/tarot/rws1909/wands-02.jpg"},"tags":["vision","choice","planning"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_02.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-03","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Three of Wands","body":"Work already set in motion is reaching outward; watch for what returns.","metadata":{"number":3,"reversed":"Expecting immediate results may obscure the progress already traveling toward you.","symbolism":"A figure stands above the sea watching ships approach beneath three wands.","question":"What progress is underway beyond your direct view?","element":"Fire","artPath":"/tarot/rws1909/wands-03.jpg"},"tags":["expansion","anticipation","progress"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_03.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-04","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Four of Wands","body":"Mark a shared milestone and make room for people who helped you reach it.","metadata":{"number":4,"reversed":"A celebration may feel hollow if belonging or rest has been postponed.","symbolism":"Four wands support a garland while people gather near home.","question":"What small victory deserves a gathering?","element":"Fire","artPath":"/tarot/rws1909/wands-04.jpg"},"tags":["welcome","milestone","community"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_04.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-05","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Five of Wands","body":"Clashing ideas can reveal energy and possibility if everyone knows the rules.","metadata":{"number":5,"reversed":"Noise and rivalry may be crowding out the common goal.","symbolism":"Five youths cross wooden wands in a lively, disorderly contest.","question":"Where is useful debate becoming needless struggle?","element":"Fire","artPath":"/tarot/rws1909/wands-05.jpg"},"tags":["friction","competition","different voices"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_05.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-06","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Six of Wands","body":"Let recognition strengthen your next step; a visible win can encourage others too.","metadata":{"number":6,"reversed":"External praise may be steering the work more than your own purpose.","symbolism":"A laurel-crowned rider passes through a crowd carrying a decorated wand.","question":"What success can you accept without minimizing it?","element":"Fire","artPath":"/tarot/rws1909/wands-06.jpg"},"tags":["recognition","momentum","encouragement"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_06.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-07","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Seven of Wands","body":"You may need to hold your ground while explaining what matters.","metadata":{"number":7,"reversed":"Defending every position can exhaust the energy needed for genuine priorities.","symbolism":"A figure on high ground faces six rising wands with one of their own.","question":"Which boundary is worth defending today?","element":"Fire","artPath":"/tarot/rws1909/wands-07.jpg"},"tags":["conviction","defense","resolve"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_07.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-08","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Eight of Wands","body":"Several things are moving at once; respond clearly and keep pace with what is real.","metadata":{"number":8,"reversed":"Hurry may be replacing intention, or a needed message may still be unsent.","symbolism":"Eight wands streak through open sky toward the ground.","question":"What deserves a prompt, uncomplicated response?","element":"Fire","artPath":"/tarot/rws1909/wands-08.jpg"},"tags":["speed","messages","movement"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_08.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-09","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Nine of Wands","body":"Experience has made you careful, and you can keep going without pretending you are untouched.","metadata":{"number":9,"reversed":"Constant vigilance may be asking for rest rather than another defense.","symbolism":"A bandaged watcher grips a wand before a row of eight others.","question":"What support would make persistence less lonely?","element":"Fire","artPath":"/tarot/rws1909/wands-09.jpg"},"tags":["resilience","caution","endurance"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_09.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-10","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Ten of Wands","body":"You have carried a great deal; finishing may require putting some weight down.","metadata":{"number":10,"reversed":"Taking every task as proof of worth can hide the help that is available.","symbolism":"A figure bends beneath ten bundled wands approaching a town.","question":"What can be shared, simplified, or set aside?","element":"Fire","artPath":"/tarot/rws1909/wands-10.jpg"},"tags":["burden","responsibility","delegation"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_10.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-11","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Page of Wands","body":"Explore a new creative direction with beginner''s permission to be clumsy.","metadata":{"number":11,"reversed":"A promising impulse may need one practical step before it fades.","symbolism":"A young messenger studies a wand in a desert landscape.","question":"What would you try if you were allowed to be new?","element":"Fire","artPath":"/tarot/rws1909/wands-11.jpg"},"tags":["curiosity","news","playful ambition"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_11.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-12","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Knight of Wands","body":"Energy favors movement; take a brave step with your eyes open.","metadata":{"number":12,"reversed":"Impulsiveness may outrun the preparation that would help you arrive.","symbolism":"A rider charges across dry ground with a wand raised.","question":"Where can you be bold without being reckless?","element":"Fire","artPath":"/tarot/rws1909/wands-12.jpg"},"tags":["boldness","travel","pursuit"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_12.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-13","version":1,"experience":"tarot","category":"Wands","state":"published","title":"Queen of Wands","body":"Lead with generous confidence and make space for your own creative fire.","metadata":{"number":13,"reversed":"Doubt or the urge to perform may be dimming an authentic voice.","symbolism":"A queen holds a sunflower and wand beside a black cat.","question":"What part of your work deserves your full presence?","element":"Fire","artPath":"/tarot/rws1909/wands-13.jpg"},"tags":["confidence","warmth","presence"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_13.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-wands-14","version":1,"experience":"tarot","category":"Wands","state":"published","title":"King of Wands","body":"A broad vision needs steady leadership and room for others to contribute.","metadata":{"number":14,"reversed":"Command may become control if you stop listening to the people doing the work.","symbolism":"A king sits on a throne marked by lions and salamanders, wand in hand.","question":"How can you lead without carrying everything alone?","element":"Fire","artPath":"/tarot/rws1909/wands-14.jpg"},"tags":["vision","leadership","enterprise"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Wands_14.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-01","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Ace of Cups","body":"A new feeling or connection can be received without demanding certainty at once.","metadata":{"number":1,"reversed":"Emotional fatigue may call for replenishment before giving more.","symbolism":"An overflowing cup rises from a hand beneath a dove and falling water.","question":"What feeling is asking to be welcomed?","element":"Water","artPath":"/tarot/rws1909/cups-01.jpg"},"tags":["openness","compassion","emotional beginning"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_01.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-02","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Two of Cups","body":"Honest reciprocity can deepen a connection; both voices belong in the room.","metadata":{"number":2,"reversed":"A bond may need a clearer conversation about balance and consent.","symbolism":"Two figures exchange cups beneath a winged lion and caduceus.","question":"Where does mutual care feel strongest?","element":"Water","artPath":"/tarot/rws1909/cups-02.jpg"},"tags":["mutuality","partnership","exchange"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_02.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-03","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Three of Cups","body":"Celebrate with people who can be happy with you, not only helpful in crisis.","metadata":{"number":3,"reversed":"Overextension or social comparison may be dulling genuine connection.","symbolism":"Three figures raise cups together amid fruit and flowers.","question":"Who would enjoy this good moment with you?","element":"Water","artPath":"/tarot/rws1909/cups-03.jpg"},"tags":["friendship","reunion","shared joy"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_03.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-04","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Four of Cups","body":"A pause may help you notice an option that boredom has blurred.","metadata":{"number":4,"reversed":"Withdrawing too long can make even a sincere offer hard to see.","symbolism":"A seated figure studies three cups while a fourth is offered from a cloud.","question":"What invitation have you barely considered?","element":"Water","artPath":"/tarot/rws1909/cups-04.jpg"},"tags":["apathy","contemplation","missed offer"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_04.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-05","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Five of Cups","body":"Loss deserves attention, and it need not erase what still stands nearby.","metadata":{"number":5,"reversed":"Fixating on what spilled may make repair or support difficult to recognize.","symbolism":"A cloaked figure faces three overturned cups while two remain upright.","question":"What can you mourn and still carry forward?","element":"Water","artPath":"/tarot/rws1909/cups-05.jpg"},"tags":["grief","disappointment","remaining support"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_05.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-06","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Six of Cups","body":"A memory or simple gesture can reconnect you with a gentler part of yourself.","metadata":{"number":6,"reversed":"Nostalgia may be polishing the past so brightly that today''s possibilities disappear.","symbolism":"Children exchange flower-filled cups in a quiet courtyard.","question":"Which old kindness could you bring into the present?","element":"Water","artPath":"/tarot/rws1909/cups-06.jpg"},"tags":["memory","kindness","familiarity"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_06.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-07","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Seven of Cups","body":"Many possibilities shimmer; compare them against your real values and resources.","metadata":{"number":7,"reversed":"Dreaming without choosing may leave every cup hovering just out of reach.","symbolism":"Seven cups float in clouds holding dazzling and unsettling visions.","question":"Which possibility still matters after the sparkle fades?","element":"Water","artPath":"/tarot/rws1909/cups-07.jpg"},"tags":["options","fantasy","discernment"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_07.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-08","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Eight of Cups","body":"Walking away from something adequate may be necessary to seek what feels meaningful.","metadata":{"number":8,"reversed":"Leaving too soon or staying from habit can each hide the deeper question.","symbolism":"A traveler leaves eight stacked cups beneath a moonlit sky.","question":"What are you outgrowing, even if it once fit?","element":"Water","artPath":"/tarot/rws1909/cups-08.jpg"},"tags":["departure","meaning","search"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_08.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-09","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Nine of Cups","body":"Enjoy the result of your effort and name what genuinely satisfies you.","metadata":{"number":9,"reversed":"Comfort may become complacency if it replaces curiosity or connection.","symbolism":"A seated figure smiles beneath a display of nine cups.","question":"What feels abundant beyond appearances?","element":"Water","artPath":"/tarot/rws1909/cups-09.jpg"},"tags":["satisfaction","pleasure","gratitude"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_09.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-10","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Ten of Cups","body":"A vision of home and connection feels possible when people make room for each other.","metadata":{"number":10,"reversed":"Idealizing harmony may silence the honest conversations that sustain it.","symbolism":"A family stands beneath a rainbow of ten cups near a home.","question":"What kind of belonging are you helping create?","element":"Water","artPath":"/tarot/rws1909/cups-10.jpg"},"tags":["belonging","harmony","shared future"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_10.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-11","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Page of Cups","body":"A small emotional surprise may invite curiosity instead of embarrassment.","metadata":{"number":11,"reversed":"Sensitive feelings may need expression rather than private rehearsal.","symbolism":"A young figure looks at a fish emerging from a cup.","question":"What unexpected feeling deserves a gentle reply?","element":"Water","artPath":"/tarot/rws1909/cups-11.jpg"},"tags":["imagination","message","tender surprise"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_11.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-12","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Knight of Cups","body":"An invitation or ideal can be followed with heart and clear boundaries.","metadata":{"number":12,"reversed":"A beautiful proposal may need practical detail before you say yes.","symbolism":"A rider offers a cup while a horse steps carefully beside water.","question":"Which invitation feels both lovely and grounded?","element":"Water","artPath":"/tarot/rws1909/cups-12.jpg"},"tags":["invitation","idealism","romance"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_12.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-13","version":1,"experience":"tarot","category":"Cups","state":"published","title":"Queen of Cups","body":"Listen with care while keeping a shore for your own feelings.","metadata":{"number":13,"reversed":"Absorbing everyone else''s mood may make your own needs hard to hear.","symbolism":"A queen studies an ornate lidded cup beside the sea.","question":"How can you care without disappearing?","element":"Water","artPath":"/tarot/rws1909/cups-13.jpg"},"tags":["empathy","depth","intuition"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_13.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-cups-14","version":1,"experience":"tarot","category":"Cups","state":"published","title":"King of Cups","body":"Strong feeling and calm judgment can coexist; steady presence helps others feel safe.","metadata":{"number":14,"reversed":"Controlled appearance may be concealing feelings that need a trustworthy outlet.","symbolism":"A king sits on a stone throne above moving waves, cup and scepter in hand.","question":"What would emotional steadiness look like in action?","element":"Water","artPath":"/tarot/rws1909/cups-14.jpg"},"tags":["emotional steadiness","wisdom","care"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Cups_14.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-01","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Ace of Swords","body":"A clear insight can cut through confusion; use it with care and precision.","metadata":{"number":1,"reversed":"A sharp idea can wound if certainty outruns understanding.","symbolism":"A hand raises a crowned sword through clouds above mountains.","question":"What truth needs a cleaner sentence?","element":"Air","artPath":"/tarot/rws1909/swords-01.jpg"},"tags":["clarity","truth","decisive thought"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_01.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-02","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Two of Swords","body":"A pause is understandable, but eventually a choice needs information and feeling together.","metadata":{"number":2,"reversed":"Avoiding a decision may be preserving a fragile peace at a cost.","symbolism":"A blindfolded figure crosses two swords before a dark sea.","question":"What fact are you unwilling to look at yet?","element":"Air","artPath":"/tarot/rws1909/swords-02.jpg"},"tags":["stalemate","choice","guarded peace"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_02.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-03","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Three of Swords","body":"Pain can be named without becoming your whole story; honesty makes room for care.","metadata":{"number":3,"reversed":"Rehearsing the hurt may keep a healing conversation from beginning.","symbolism":"Three swords pierce a heart beneath a rainy sky.","question":"What pain deserves acknowledgment rather than argument?","element":"Air","artPath":"/tarot/rws1909/swords-03.jpg"},"tags":["heartache","honest pain","release"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_03.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-04","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Four of Swords","body":"Rest is a strategy, not a reward you must earn after collapse.","metadata":{"number":4,"reversed":"Retreat may have become avoidance if the same issue waits untouched.","symbolism":"A recumbent figure rests beneath stained glass and three hanging swords.","question":"What kind of rest would actually restore you?","element":"Air","artPath":"/tarot/rws1909/swords-04.jpg"},"tags":["rest","recovery","reflection"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_04.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-05","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Five of Swords","body":"Winning an argument may still cost trust; consider what outcome you truly want.","metadata":{"number":5,"reversed":"An old conflict can be repaired if pride stops writing the whole script.","symbolism":"A figure gathers swords while others retreat beneath a troubled sky.","question":"Is this victory worth the relationship it may strain?","element":"Air","artPath":"/tarot/rws1909/swords-05.jpg"},"tags":["conflict","cost","hollow victory"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_05.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-06","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Six of Swords","body":"A difficult crossing can still be progress; accept help for the journey.","metadata":{"number":6,"reversed":"Carrying every old worry into the new place may make arrival harder.","symbolism":"A boat carries travelers and six swords across water toward distant land.","question":"What are you ready to leave on the far shore?","element":"Air","artPath":"/tarot/rws1909/swords-06.jpg"},"tags":["transition","passage","gradual relief"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_06.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-07","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Seven of Swords","body":"A clever approach can help you work around a real obstacle.","metadata":{"number":7,"reversed":"Secrecy may be protecting convenience instead of integrity.","symbolism":"A figure slips away from a camp carrying five swords and leaving two behind.","question":"What would a more honest strategy look like?","element":"Air","artPath":"/tarot/rws1909/swords-07.jpg"},"tags":["strategy","secrecy","independence"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_07.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-08","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Eight of Swords","body":"The situation may be hard, yet some boundaries may be less fixed than they appear.","metadata":{"number":8,"reversed":"Self-blame is not a map out; ask what support or information changes the scene.","symbolism":"A bound, blindfolded figure stands among swords with open ground nearby.","question":"Which limit is real, and which one needs testing?","element":"Air","artPath":"/tarot/rws1909/swords-08.jpg"},"tags":["constraint","fear","limited view"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_08.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-09","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Nine of Swords","body":"A worry may feel enormous at night; bring it into daylight and compassionate company.","metadata":{"number":9,"reversed":"Ignoring distress can make it louder; consider a smaller, practical response.","symbolism":"A figure wakes in bed beneath nine swords on a dark wall.","question":"What would help this thought feel less solitary?","element":"Air","artPath":"/tarot/rws1909/swords-09.jpg"},"tags":["anxiety","rumination","night thoughts"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_09.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-10","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Ten of Swords","body":"Something has reached a painful limit; the dawn suggests that an ending is not all there is.","metadata":{"number":10,"reversed":"Replaying the collapse can obscure the first signs of recovery.","symbolism":"A prone figure lies beneath ten swords as light rises at the horizon.","question":"What can you stop carrying after this ending?","element":"Air","artPath":"/tarot/rws1909/swords-10.jpg"},"tags":["ending","exhaustion","dawn"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_10.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-11","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Page of Swords","body":"Ask precise questions and keep learning before making a firm claim.","metadata":{"number":11,"reversed":"A restless mind may turn curiosity into suspicion or noise.","symbolism":"A young figure holds a raised sword in a windy landscape.","question":"Which question would improve your understanding?","element":"Air","artPath":"/tarot/rws1909/swords-11.jpg"},"tags":["curiosity","alertness","questions"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_11.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-12","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Knight of Swords","body":"Move decisively when clarity is earned and the stakes are understood.","metadata":{"number":12,"reversed":"Charging forward may leave empathy and context behind.","symbolism":"An armored rider races into the wind with sword extended.","question":"Where should you slow down just enough to see others?","element":"Air","artPath":"/tarot/rws1909/swords-12.jpg"},"tags":["speed","conviction","challenge"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_12.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-13","version":1,"experience":"tarot","category":"Swords","state":"published","title":"Queen of Swords","body":"A clear boundary can be kind when it is honest and well timed.","metadata":{"number":13,"reversed":"Distance or criticism may be standing in for a vulnerable truth.","symbolism":"A queen holds an upright sword while extending an open hand.","question":"What can you say plainly without becoming harsh?","element":"Air","artPath":"/tarot/rws1909/swords-13.jpg"},"tags":["discernment","candor","boundaries"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_13.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-swords-14","version":1,"experience":"tarot","category":"Swords","state":"published","title":"King of Swords","body":"Use knowledge and responsibility to make a fair, considered decision.","metadata":{"number":14,"reversed":"Intellectual certainty can become detached from the people affected.","symbolism":"A crowned king sits with an upright sword beneath a patterned sky.","question":"How will you pair clear thinking with care?","element":"Air","artPath":"/tarot/rws1909/swords-14.jpg"},"tags":["reason","ethics","judgment"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Swords_14.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-01","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Ace of Pentacles","body":"A tangible opportunity is present; give it a small, workable first step.","metadata":{"number":1,"reversed":"A promising resource may be overlooked while waiting for perfect conditions.","symbolism":"A hand offers a coin above a garden path and archway.","question":"What practical seed can you plant now?","element":"Earth","artPath":"/tarot/rws1909/pentacles-01.jpg"},"tags":["opportunity","resources","practical beginning"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_01.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-02","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Two of Pentacles","body":"Several demands can be balanced if you stay flexible about timing.","metadata":{"number":2,"reversed":"Constant juggling may be hiding a need to drop or delegate one task.","symbolism":"A figure loops two coins while ships rise and fall behind them.","question":"Which commitment needs a different rhythm?","element":"Earth","artPath":"/tarot/rws1909/pentacles-02.jpg"},"tags":["adaptation","juggling","rhythm"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_02.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-03","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Three of Pentacles","body":"Good work grows through skill, feedback, and shared expertise.","metadata":{"number":3,"reversed":"Working alone or resisting feedback may limit a promising project.","symbolism":"Artisans confer beneath the arches of a building in progress.","question":"Whose perspective could strengthen this work?","element":"Earth","artPath":"/tarot/rws1909/pentacles-03.jpg"},"tags":["craft","collaboration","learning"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_03.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-04","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Four of Pentacles","body":"Protecting what you have can create stability when it comes from clarity.","metadata":{"number":4,"reversed":"Holding too tightly may make resources and relationships feel smaller.","symbolism":"A figure grips coins at crown, chest, and feet outside a city.","question":"What are you protecting, and at what cost?","element":"Earth","artPath":"/tarot/rws1909/pentacles-04.jpg"},"tags":["security","holding","control"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_04.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-05","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Five of Pentacles","body":"Difficulty is real; support may be closer than it first appears.","metadata":{"number":5,"reversed":"Shame can keep you outside a door that would open if you knocked.","symbolism":"Two figures walk in snow beside a lit stained-glass window.","question":"What help could you ask for without apology?","element":"Earth","artPath":"/tarot/rws1909/pentacles-05.jpg"},"tags":["hardship","exclusion","help"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_05.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-06","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Six of Pentacles","body":"Resources move best with attention to dignity and genuine need.","metadata":{"number":6,"reversed":"A gift can create imbalance if generosity becomes control.","symbolism":"A figure weighs coins and gives to two people beneath the scales.","question":"How can giving or receiving feel more equal?","element":"Earth","artPath":"/tarot/rws1909/pentacles-06.jpg"},"tags":["giving","receiving","fairness"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_06.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-07","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Seven of Pentacles","body":"Progress takes tending; pause to judge what is growing before planting more.","metadata":{"number":7,"reversed":"Waiting alone will not fix a method that needs adjustment.","symbolism":"A gardener leans on a tool and studies a vine of coins.","question":"What investment deserves patience, and what needs revision?","element":"Earth","artPath":"/tarot/rws1909/pentacles-07.jpg"},"tags":["patience","assessment","investment"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_07.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-08","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Eight of Pentacles","body":"Repetition is building skill; care in the small parts matters.","metadata":{"number":8,"reversed":"Perfectionism may make practice feel like punishment instead of learning.","symbolism":"A craftsperson carves coin after coin beside a workbench.","question":"Which skill improves with one more honest attempt?","element":"Earth","artPath":"/tarot/rws1909/pentacles-08.jpg"},"tags":["practice","mastery","detail"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_08.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-09","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Nine of Pentacles","body":"Enjoy the stability you helped create and the freedom it makes possible.","metadata":{"number":9,"reversed":"Comfort may be isolating if it never opens toward connection.","symbolism":"A figure stands in a fruitful garden with a falcon and nine coins.","question":"What have you cultivated that lets you breathe?","element":"Earth","artPath":"/tarot/rws1909/pentacles-09.jpg"},"tags":["independence","cultivation","pleasure"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_09.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-10","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Ten of Pentacles","body":"Think beyond the immediate gain toward what can support others over time.","metadata":{"number":10,"reversed":"Inherited expectations may need updating to fit the people living with them.","symbolism":"Generations gather beneath an arch with dogs and patterned coins.","question":"What kind of legacy are your ordinary choices building?","element":"Earth","artPath":"/tarot/rws1909/pentacles-10.jpg"},"tags":["legacy","household","long view"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_10.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-11","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Page of Pentacles","body":"A new practical skill deserves attention and a patient beginning.","metadata":{"number":11,"reversed":"Planning to learn can become a way to postpone the first lesson.","symbolism":"A young figure studies a coin in a green field.","question":"What useful skill are you ready to practice?","element":"Earth","artPath":"/tarot/rws1909/pentacles-11.jpg"},"tags":["study","practical curiosity","opportunity"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_11.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-12","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Knight of Pentacles","body":"Slow, repeatable action can carry a plan farther than a dramatic start.","metadata":{"number":12,"reversed":"Routine may need a fresh reason if it has turned into mere inertia.","symbolism":"A rider sits on a still dark horse holding a coin above worked land.","question":"What small action would be worth repeating?","element":"Earth","artPath":"/tarot/rws1909/pentacles-12.jpg"},"tags":["consistency","reliability","steady effort"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_12.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-13","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"Queen of Pentacles","body":"Practical care can make a home, project, or body feel supported.","metadata":{"number":13,"reversed":"Caring for everyone else may leave your own resources unattended.","symbolism":"A queen holds a coin in a lush garden while a rabbit waits nearby.","question":"What needs both kindness and a practical plan?","element":"Earth","artPath":"/tarot/rws1909/pentacles-13.jpg"},"tags":["care","resourcefulness","grounded comfort"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_13.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]},{"id":"tarot-pentacles-14","version":1,"experience":"tarot","category":"Pentacles","state":"published","title":"King of Pentacles","body":"Experience and resources can be used to build something lasting and generous.","metadata":{"number":14,"reversed":"Success may harden into control if you forget what it was meant to serve.","symbolism":"A king sits among vines and carved bulls with a coin in hand.","question":"How can stability serve more than yourself?","element":"Earth","artPath":"/tarot/rws1909/pentacles-14.jpg"},"tags":["stewardship","stability","generosity"],"sources":[{"url":"https://commons.wikimedia.org/wiki/File%3ARWS1909_-_Pentacles_14.jpeg","license":"Public domain","verifiedAt":"2026-11-02"}]}]'::jsonb);
